<script setup lang="ts">import { computed } from 'vue';import { useRoute,useRouter } from 'vue-router';import NavIcon from './NavIcon.vue';const route=useRoute(),router=useRouter();const tabs=[{key:'today',name:'today',label:'概览',icon:'overview'},{key:'training',name:'plan',label:'训练',icon:'training'},{key:'diet',name:'diet',label:'饮食',icon:'diet'},{key:'report',name:'shaping',label:'报告',icon:'report'},{key:'library',name:'library',label:'动作库',icon:'library'}] as const;const active=computed(()=>route.name==='log'?'training':route.name==='review'?'report':String(route.name))</script>
<template><nav class="mobile-tabs" aria-label="移动端主要功能"><button v-for="tab in tabs" :key="tab.key" :class="{active:active===tab.key}" :aria-current="active===tab.key?'page':undefined" @click="router.push({name:tab.name})"><NavIcon :name="tab.icon"/><span>{{tab.label}}</span></button></nav></template>
